/**
 * Tenant wrangler-config generation.
 *
 * A site's directory (`tenants/<id>/`) and the shared infrastructure are the source of truth for deployed sites. For
 * every site this module writes a standalone frontend Worker config into the site's generated folder,
 * `.generated/sites/<id>/wrangler.jsonc`, from the shared base in `wrangler-base.ts`
 * and the site's modules. The files are gitignored and deterministic, and are regenerated by `hearthlog build`,
 * the deploy tools, and `pnpm check:tenants`. Paths in them are relative to that folder, as wrangler resolves them.
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";

import { moduleSettingProblem, type ModuleManifest } from "@hearthlog/contracts";

import { WRANGLER_BASE } from "./wrangler-base.js";
import { activeIntegrations } from "@hearthlog/contracts/integrations/kinds";
import { gatewayEntryPath, loadModules, modulesForFeatures } from "../compose/compose-modules.js";
import {
    gallerySweeperId,
    infrastructureFor,
    loadTenantConfig,
    REPOSITORY_ROOT,
    TenantConfigError,
    type InfrastructureDefinition,
    type ResolvedSite,
    type SiteStack,
} from "./tenant-config.js";

/** Strip line and block comments from wrangler's JSONC without touching strings. */
export function stripJsonComments(jsonc: string): string {
    let result = "";
    let index = 0;
    let inString = false;
    while (index < jsonc.length) {
        const char = jsonc[index];
        const next = jsonc[index + 1];
        if (inString) {
            result += char;
            if (char === "\\") {
                result += next ?? "";
                index += 2;
                continue;
            }
            if (char === '"') inString = false;
            index += 1;
            continue;
        }
        if (char === '"') {
            inString = true;
            result += char;
            index += 1;
            continue;
        }
        if (char === "/" && next === "/") {
            while (index < jsonc.length && jsonc[index] !== "\n") index += 1;
            continue;
        }
        if (char === "/" && next === "*") {
            index += 2;
            while (
                index < jsonc.length &&
                !(jsonc[index] === "*" && jsonc[index + 1] === "/")
            ) {
                index += 1;
            }
            index += 2;
            continue;
        }
        result += char;
        index += 1;
    }
    return result;
}

/** The folder a site's generated frontend Worker files are in. */
export function siteConfigDirectory(siteId: string): string {
    return dirname(gatewayEntryPath(siteId));
}

/** Where a site's frontend Worker config is written. */
export function wranglerConfigPath(siteId: string): string {
    return join(siteConfigDirectory(siteId), "wrangler.jsonc");
}

/** Where `vite build` writes a site's assets, from the repository root; the default site builds into `build`. */
export function siteBuildDirectory(siteId: string): string {
    return siteId === "st" ? "build" : `build/${siteId}`;
}

/** The server declarations of the modules a site enables, in module order. */
export function serverDeclarations(features: readonly string[]): Array<NonNullable<ModuleManifest["server"]>> {
    return modulesForFeatures(loadModules(), features).flatMap(({ manifest }) => manifest.server ? [manifest.server] : []);
}

/** `run_worker_first` entries for API prefixes: the prefix and everything beneath it. */
export function workerFirstEntries(prefixes: readonly string[]): string[] {
    // Wrangler rejects a rule another makes redundant, so a prefix beneath a listed one is left out
    // (`/api/invoice-generation/logs` is served by the `/api/invoice-generation/*` rule).
    const outer = prefixes.filter((prefix) => !prefixes.some((other) => other !== prefix && prefix.startsWith(`${other}/`)));
    return outer.flatMap((prefix) => [prefix, `${prefix}/*`]);
}

/** The core's `run_worker_first` entries, then those of the site's modules. */
export function siteWorkerFirst(features: readonly string[]): string[] {
    return [...WRANGLER_BASE.assets.run_worker_first, ...workerFirstEntries(serverDeclarations(features).flatMap((server) => server.routes ?? []))];
}

/**
 * The bindings and variables a site's modules need, from their manifests.
 * A `resource` names a key of the tenant's infrastructure; a `setting` names a key of the module's block in
 * `infrastructure.moduleSettings`, checked against the format the manifest declares.
 */
export function moduleBindings(
    features: readonly string[],
    infrastructure: InfrastructureDefinition,
): { r2: Array<{ binding: string; bucket_name: string }>; images: boolean; vars: Record<string, string> } {
    const keyed = infrastructure as unknown as Record<string, string | undefined>;
    const lookup = (resource: string): string => {
        const value = keyed[resource];
        if (!value) throw new Error(`The infrastructure has no "${resource}"`);
        return value;
    };
    const result = { r2: [] as Array<{ binding: string; bucket_name: string }>, images: false, vars: {} as Record<string, string> };
    for (const { manifest } of modulesForFeatures(loadModules(), features)) {
        const server = manifest.server;
        if (!server) continue;
        for (const binding of server.bindings ?? []) {
            if (binding.type === "r2") result.r2.push({ binding: binding.binding, bucket_name: lookup(binding.resource) });
            else result.images = true;
        }
        const settings = infrastructure.moduleSettings?.[manifest.id] ?? {};
        const declared = new Set<string>();
        for (const variable of server.vars ?? []) {
            if ("resource" in variable) {
                const value = variable.optional ? keyed[variable.resource] : lookup(variable.resource);
                if (value) result.vars[variable.name] = value;
                continue;
            }
            declared.add(variable.setting);
            const value = settings[variable.setting];
            const label = `moduleSettings.${manifest.id}.${variable.setting}`;
            if (value === undefined) {
                if (variable.optional) continue;
                throw new TenantConfigError(`${label} is required by ${manifest.id}`);
            }
            const problem = moduleSettingProblem(variable, value);
            if (problem) throw new TenantConfigError(`${label} ${problem}`);
            result.vars[variable.name] = value;
        }
        const unknown = Object.keys(settings).filter((key) => !declared.has(key));
        if (unknown.length) throw new TenantConfigError(`moduleSettings.${manifest.id}: unknown key "${unknown[0]}" (known keys: ${[...declared].join(", ") || "none"})`);
    }
    return result;
}

/**
 * Derive the standalone wrangler config for one site. Everything not tenant-specific (compatibility, assets
 * behavior, observability, smart placement) comes from the shared base; the identity, vars, and bindings come from
 * tenants.json and the site's modules. Pass the site's own infrastructure (`infrastructureFor`): a site on its own
 * stack binds only its own Ledger and buckets. `sweeps` marks the site that sweeps the public Gallery bucket it owns.
 */
export function buildTenantWranglerConfig(
    site: ResolvedSite,
    infrastructure: InfrastructureDefinition,
    options: { sweeps?: boolean } = {},
): Record<string, unknown> {
    const modules = moduleBindings(site.features, infrastructure);
    const scheduled = serverDeclarations(site.features).some((server) => server.scheduled);
    const base = WRANGLER_BASE;
    const directory = siteConfigDirectory(site.id);
    return {
        name: site.id,
        ...(site.deployment?.accountId ? { account_id: site.deployment.accountId } : {}),
        main: `./${relative(directory, gatewayEntryPath(site.id))}`,
        compatibility_date: base.compatibility_date,
        compatibility_flags: base.compatibility_flags,
        // Sites live on their Access-protected workers.dev hostname only:
        // version preview hostnames are never enabled.
        workers_dev: true,
        preview_urls: false,
        assets: {
            directory: relative(directory, join(REPOSITORY_ROOT, siteBuildDirectory(site.id))),
            binding: base.assets.binding,
            not_found_handling: base.assets.not_found_handling,
            run_worker_first: siteWorkerFirst(site.features),
        },
        observability: base.observability,
        placement: base.placement,
        vars: {
            LEDGER_ADMIN_EMAIL: infrastructure.ledgerAdminEmail,
            STOR_AUTHORIZED_EMAILS: site.authorizedEmails.join(","),
            STOR_ADMIN_ENABLED: String(site.admin),
            ...modules.vars,
            AI_CAPABILITIES: site.ai.join(","),
            INTEGRATIONS: integrationsVariable(site),
            ...siteIdentityVariables(site, infrastructure),
        },
        services: [
            {
                binding: "LEDGER",
                service: infrastructure.ledgerWorker,
            },
        ],
        // Each site's gateway entry bundles only the server code of the modules it enables.
        ...(modules.images ? { images: base.images } : {}),
        ratelimits: base.ratelimits,
        ...(options.sweeps && scheduled ? { triggers: base.triggers } : {}),
        ai: base.ai,
        r2_buckets: [
            {
                binding: "CALENDAR_FEEDS",
                bucket_name: infrastructure.calendarFeedsBucket,
            },
            ...modules.r2,
        ],
    };
}

/**
 * The site that sweeps the shared stack's public Gallery bucket: the configured one (`gallerySweeper`), else the first
 * site without a stack of its own (a site with its own stack sweeps its own bucket). Two sweepers on one bucket would race.
 */
export function sweepsSharedStack(
    stacks: readonly SiteStack[],
    infrastructure: Pick<InfrastructureDefinition, "gallerySweeper">,
    site: Pick<ResolvedSite, "id" | "deployment">,
): boolean {
    return Boolean(site.deployment) || gallerySweeperId(stacks, infrastructure) === site.id;
}

/**
 * Who the site is and where its calendar feeds are served: the feed UIDs carry
 * the site's own hostname, and the drawer returns URLs on the feed Worker.
 */
export function siteIdentityVariables(
    site: ResolvedSite,
    infrastructure: Pick<InfrastructureDefinition, "calendarPublicOrigin">,
): Record<string, string> {
    return {
        SITE_ID: site.id,
        SITE_ORIGIN: site.hostname,
        CALENDAR_FEED_ORIGIN: infrastructure.calendarPublicOrigin,
    };
}

/** The non-secret integration list a site's Worker accepts, as the INTEGRATIONS variable. */
export function integrationsVariable(site: ResolvedSite): string {
    return JSON.stringify(activeIntegrations(site.integrations));
}

/**
 * Generate the standalone wrangler config of a site (all of them without an id). A build passes its own site, whose modules are the only ones in its catalog. Returns the written paths.
 */
export async function generateTenantWranglerConfigs(siteId?: string): Promise<string[]> {
    const { infrastructure, sites, stacks } = await loadTenantConfig(undefined, { only: siteId });
    const written: string[] = [];
    for (const site of sites) {
        const path = wranglerConfigPath(site.id);
        const config = buildTenantWranglerConfig(site, infrastructureFor(site, infrastructure), { sweeps: sweepsSharedStack(stacks, infrastructure, site) });
        await mkdir(dirname(path), { recursive: true });
        await writeFile(path, `${JSON.stringify(config, null, 2)}\n`, "utf8");
        written.push(path);
    }
    return written;
}

/** Where a site's wrangler config lives (relative to the repository root, where the tools run wrangler). */
export interface WranglerTarget {
    config: string;
    /** --env value; null means the config is standalone (no --env). */
    envKey: string | null;
}

export function resolveFrontendWranglerTarget(siteId: string): WranglerTarget {
    return { config: relative(REPOSITORY_ROOT, wranglerConfigPath(siteId)), envKey: null };
}

export async function ensureTenantWranglerConfigs(): Promise<void> {
    const written = await generateTenantWranglerConfigs();
    if (written.length > 0 && process.env.STOR_VERBOSE) {
        for (const path of written) {
            console.log(`Generated ${path.replace(`${REPOSITORY_ROOT}/`, "")}`);
        }
    }
}
